from pathlib import Path
import json,struct,math,hashlib
import numpy as np
root=Path('experiments/gpu-physics');base=root/'artifacts/gpu-solver-qualification/desktop-baseline';trace=base/'rain-coupled-anchor-audit/baseline/trace.jsonl';out=base/'rain-revolute-basis-audit';out.mkdir(exist_ok=False)
f=lambda x:struct.unpack('!f',bytes.fromhex(x))[0]
v=lambda x:np.array([f(t) for t in x])
def mul(a,b):return np.r_[a[3]*b[:3]+b[3]*a[:3]+np.cross(a[:3],b[:3]),a[3]*b[3]-np.dot(a[:3],b[:3])]
def inv(q):return np.r_[-q[:3],q[3]]
def rotate(q,x):return x+2*np.cross(q[:3],np.cross(q[:3],x)+q[3]*x)
def axes(qa,qb,j):
 a=mul(qa,v(j['frame_a_rotation']));b=mul(qb,v(j['frame_b_rotation']))
 if np.dot(a,b)<0:b=-b
 rel=mul(inv(a),b)
 return np.column_stack([.5*rotate(a,rel[3]*e+np.cross(rel[:3],e)) for e in [np.array([1.,0,0]),np.array([0.,1,0])]])
previous=None;rows=[];end_errors=[];flags=[]
with trace.open() as source:
 for line in source:
  d=json.loads(line);bs={x['identity']:x for x in d['bodies']};starts=dict(zip(d['body_storage_order'],d['host_state']['step_start_bodies']));js={j['identity']:j for j in d['joints'] if j['kind']==1};assert len(js)==12
  for id,j in js.items():
   stored=np.column_stack([v(j['weld_linear_impulse']),v(j['weld_angular_impulse'])]);actual=axes(v(bs[j['a']]['rot']),v(bs[j['b']]['rot']),j)
   if j['revolute_axes_step']==d['frame']:end_errors.append(float(np.max(abs(actual-stored))))
   else:flags.append([d['frame'],id,j['revolute_axes_step']])
   if previous:
    old=previous[id];cached=np.column_stack([v(old['weld_linear_impulse']),v(old['weld_angular_impulse'])]);fresh=axes(v(starts[j['a']]['rot']),v(starts[j['b']]['rot']),j)
    impulse=v(old['perp_impulse']);old_torque=cached@impulse;new_torque=fresh@impulse
    rows.append({'frame':d['frame'],'joint':id,'axis_max_component_change':float(np.max(abs(fresh-cached))),'impulse_vector_change':float(np.linalg.norm(new_torque-old_torque)),'old_impulse_vector_norm':float(np.linalg.norm(old_torque))})
  previous=js
assert len(rows)==12*119 and len(end_errors)+len(flags)==1440
result={'scope':'Independent float64 geometry reconstruction of previous saved revolute bases versus next-frame preparation, using all12hinges in original120step replay. This checks boundary basis continuity, not total work or physical acceptance.','frames':120,'hinges':12,'boundary_observations':len(rows),'updated_axis_observations':len(end_errors),'stale_step_records':flags,'maximum_end_axis_component_error':max(end_errors),'maximum_boundary_axis_component_change':max(x['axis_max_component_change'] for x in rows),'maximum_boundary_cached_torque_impulse_change':max(x['impulse_vector_change'] for x in rows),'maximum_cached_torque_impulse_norm':max(x['old_impulse_vector_norm'] for x in rows),'worst_change':max(rows,key=lambda x:x['impulse_vector_change']),'trace_sha256':hashlib.sha256(trace.read_bytes()).hexdigest()}
(out/'rows.json').write_text(json.dumps(rows,indent=2)+'\n');(out/'summary.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
